#[test]
fn a_border_runs_round_the_whole_outline_or_along_the_edges_it_references() {
    let island = objects()
        .into_iter()
        .find(|o| o.kind == ObjectType::TrafficIsland)
        .expect("the island");
    let corner = |s, t| raised(s, t, 0.0);
    let [curb, paint] = &island.borders[..] else {
        panic!("two borders: {:?}", island.borders);
    };

    // All four edges, the closing one too, level with the outline's base.
    assert_eq!((curb.kind.as_str(), curb.width), ("curb", 0.3));
    let round = [
        (64.0, -1.0),
        (70.0, -1.0),
        (70.0, 1.0),
        (64.0, 1.0),
        (64.0, -1.0),
    ];
    assert_eq!(curb.pieces.len(), 4);
    for (k, piece) in curb.pieces.iter().enumerate() {
        let ((s0, t0), (s1, t1)) = (round[k], round[k + 1]);
        assert_piece(
            piece,
            corner(s0, t0),
            corner(s1, t1),
            0.3,
            &format!("edge {k}"),
        );
    }

    // Corners 1 and 2 only: the s = 70 end.
    assert_eq!((paint.kind.as_str(), paint.width), ("paint", 0.5));
    assert_eq!(paint.pieces.len(), 1);
    assert_piece(
        &paint.pieces[0],
        corner(70.0, -1.0),
        corner(70.0, 1.0),
        0.5,
        "end",
    );
}

#[test]
fn an_object_stands_upright_on_a_banked_road() {
    // Road 2 banks 0.15 rad about its reference line, so the kiosk at t = -5
    // is 5 cos 0.15 right of it and 5 sin 0.15 down. Its zOffset raises it
    // straight up, and it stands level across the bank.
    let kiosk = &on("2")[0];
    let Shape::Solid {
        position,
        heading,
        pitch,
        roll,
        ..
    } = kiosk.shape
    else {
        panic!("a solid: {:?}", kiosk.shape);
    };
    let (sin, cos) = 0.15_f32.sin_cos();
    let want = Point::new(20.0, -80.0 - 5.0 * cos, -5.0 * sin + 0.2);
    assert_near(position, want, "kiosk");
    assert!(
        heading.abs() < 1e-6 && pitch.abs() < 1e-6 && roll.abs() < 1e-6,
        "{heading}, {pitch}, {roll}"
    );
}

#[test]
fn a_repeat_moves_the_outlines_to_each_step() {
    // Road 2 banks 0.15 rad, but each planter stands level: its frame is the
    // network's axes at the bank's surface at t = 5, its height straight up.
    let planters: Vec<Object> = on("2")
        .into_iter()
        .filter(|o| o.name == "Planter")
        .collect();
    assert_eq!(planters.len(), 4);
    let (sin, cos) = 0.15_f32.sin_cos();
    for (planter, s) in planters.iter().zip([5.0, 15.0, 25.0, 35.0]) {
        let (corners, closed) = outline(planter);
        assert!(closed);
        for (corner, (u, v)) in corners
            .iter()
            .zip([(0.0, 0.0), (1.5, 0.0), (1.5, 1.0), (0.0, 1.0)])
        {
            let base = Point::new(s + u, -80.0 + 5.0 * cos + v, 5.0 * sin);
            let what = format!("planter at s={s} ({u}, {v})");
            assert_corner(corner, base, 0.6, &what);
        }
    }
}

#[test]
fn a_border_tilts_with_a_banked_road() {
    // Road 2 banks 0.15 rad about the line y = -80, so its surface is
    // z = (y + 80) tan 0.15. The pad's kerb lies in it all the way across.
    let pads: Vec<Object> = on("2").into_iter().filter(|o| o.name == "Pad").collect();
    let [pad] = &pads[..] else {
        panic!("one pad: {pads:?}");
    };
    let [kerb] = &pad.borders[..] else {
        panic!("one border: {:?}", pad.borders);
    };
    assert_eq!(kerb.pieces.len(), 4);
    let tan = 0.15_f32.tan();
    for p in kerb.pieces.iter().flatten() {
        let off = p.z - (p.y + 80.0) * tan;
        assert!(off.abs() < 1e-5, "{p:?} is {off} m off the road");
    }
}

#[test]
fn a_stretch_ending_on_a_section_boundary_stays_out_of_the_next_section() {
    let section = |s: f64| {
        format!(
            r#"<laneSection s="{s}"><center><lane id="0" type="none"/></center><right>
            <lane id="-1" type="driving"><width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
            </right></laneSection>"#
        )
    };
    let xodr = format!(
        r#"<OpenDRIVE><header/><road id="1" length="100" junction="-1"><planView>
        <geometry s="0" x="0" y="0" hdg="0" length="100"><line/></geometry></planView>
        <lanes>{}{}</lanes><objects>
        <object id="rail" type="barrier" s="0" t="-4" zOffset="0" height="1" width="0.3">
          <repeat s="0" length="50" distance="0" tStart="-4" tEnd="-4" widthStart="0.3" widthEnd="0.3" heightStart="1" heightEnd="1" zOffsetStart="0" zOffsetEnd="0"/>
        </object>
        <object id="post" type="pole" s="50" t="-4" zOffset="0" height="1" radius="0.1"/>
        </objects></road></OpenDRIVE>"#,
        section(0.0),
        section(50.0),
    );
    let (net, prov) = xodr::load_str_with_provenance(&xodr).unwrap();
    let lane = |section: usize| {
        prov.lanes
            .iter()
            .find(|p| p.section == section)
            .unwrap()
            .lane
    };
    let lanes_of = |name: &str| {
        let id = prov
            .objects
            .iter()
            .find(|p| p.od_id == name)
            .unwrap()
            .object;
        net.object(id).unwrap().lanes.clone()
    };
    assert_eq!(lanes_of("rail"), [lane(0)]);
    assert_eq!(lanes_of("post"), [lane(1)]);
}

#[test]
fn a_repeat_or_marking_with_too_many_copies_is_left_out_with_a_warning() {
    let xodr = |object: &str| {
        format!(
            r#"<OpenDRIVE><header/><road id="1" length="100" junction="-1"><planView>
            <geometry s="0" x="0" y="0" hdg="0" length="100"><line/></geometry></planView>
            <lanes><laneSection s="0"><center><lane id="0" type="none"/></center><right>
            <lane id="-1" type="driving"><width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
            </right></laneSection></lanes><objects>{object}</objects></road></OpenDRIVE>"#
        )
    };
    let warned = |object: &str| xodr::Warning::TooManyCopies {
        road_id: "1".into(),
        object_id: object.into(),
    };
    let posts = r#"<object id="posts" type="pole" s="0" t="-5" height="1" radius="0.1">
        <repeat s="0" length="100" distance="0.0001"/></object>"#;
    let (net, prov) = xodr::load_str_with_provenance(&xodr(posts)).unwrap();
    assert!(net.objects().is_empty());
    assert_eq!(prov.warnings, [warned("posts")]);

    let crossing = r#"<object id="crossing" type="crosswalk" s="50" t="-2" zOffset="0">
        <outlines><outline id="0" closed="true">
          <cornerLocal id="0" u="0" v="0" z="0" height="0"/><cornerLocal id="1" u="3" v="0" z="0" height="0"/>
          <cornerLocal id="2" u="3" v="3" z="0" height="0"/><cornerLocal id="3" u="0" v="3" z="0" height="0"/>
        </outline></outlines>
        <markings><marking width="0.5" color="white" lineLength="0.00001" spaceLength="0.00001">
          <cornerReference id="0"/><cornerReference id="1"/></marking></markings></object>"#;
    let (net, prov) = xodr::load_str_with_provenance(&xodr(crossing)).unwrap();
    assert_eq!(net.objects().len(), 1, "the outline stays");
    assert!(net.objects()[0].markings[0].pieces.is_empty());
    assert_eq!(prov.warnings, [warned("crossing")]);
}

fn on_straight_road(objects: &str) -> String {
    format!(
        r#"<OpenDRIVE><header/><road id="1" length="100" junction="-1"><planView>
        <geometry s="0" x="0" y="0" hdg="0" length="100"><line/></geometry></planView>
        <lanes><laneSection s="0"><center><lane id="0" type="none"/></center><right>
        <lane id="-1" type="driving"><width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
        </right></laneSection></lanes><objects>{objects}</objects></road></OpenDRIVE>"#
    )
}

